12	static void mi_page_map_cannot_commit(void) {
13	  _mi_warning_message("unable to commit the allocation page-map on-demand\n" );
14	}
15	
16	#if MI_PAGE_MAP_FLAT
17	
18	// The page-map contains a byte for each 64kb slice in the address space.
19	// For an address `a` where `ofs = _mi_page_map[a >> 16]`:
20	// 0 = unused
21	// 1 = the slice at `a & ~0xFFFF` is a mimalloc page.
22	// 1 < ofs <= 127 = the slice is part of a page, starting at `(((a>>16) - ofs - 1) << 16)`.
23	//
24	// 1 byte per slice => 1 TiB address space needs a 2^14 * 2^16 = 16 MiB page map.
25	// A full 256 TiB address space (48 bit) needs a 4 GiB page map.
26	// A full 4 GiB address space (32 bit) needs only a 64 KiB page map.
27	
28	// Use an initial empty page map so `free(NULL)` works even if mimalloc is not yet initialized (issue #1341)
29	static uint8_t mi_page_map_empty[1] = { 1 };      // _mi_ptr_page(NULL) == NULL
30	
31	mi_decl_hidden mi_decl_cache_align _Atomic(uint8_t*) _mi_page_map   = mi_page_map_empty;
32	mi_decl_hidden _Atomic(void*)  _mi_page_map_max_address = NULL;
33	static mi_memid_t   mi_page_map_memid;
34	
35	#define MI_PAGE_MAP_ENTRIES_PER_COMMIT_BIT   MI_ARENA_SLICE_SIZE
36	static mi_bitmap_t* mi_page_map_commit; // one bit per committed 64 KiB entries
37	
38	mi_decl_nodiscard static bool mi_page_map_ensure_committed(size_t idx, size_t slice_count);
39	
40	bool _mi_page_map_init(void) {
41	  size_t vbits = (size_t)mi_option_get_clamp(mi_option_max_vabits, 0, MI_MAX_VABITS);
42	  if (vbits == 0) {
43	    vbits = _mi_os_virtual_address_bits();
44	    #if MI_ARCH_X64  // canonical address is limited to the first 128 TiB
45	    if (vbits >= 48) { vbits = 47; }
46	    #endif
47	  }
48	  if (vbits < MI_ARENA_SLICE_SHIFT) {
49	    vbits = MI_ARENA_SLICE_SHIFT;
50	  }
51	  if (vbits < MI_MIN_VABITS) {    // cover at least this much for a faster _mi_checked_ptr
52	    vbits = MI_MIN_VABITS;
53	  }
54	  if (vbits > MI_MAX_VABITS) {    // limit page map size even if more virtual addresses are available
55	    vbits = MI_MAX_VABITS;
56	  }
57	
58	  // Allocate the page map and commit bits
59	  mi_atomic_store_ptr_release(void, &_mi_page_map_max_address, (void*)(vbits >= MI_SIZE_BITS ? (SIZE_MAX - MI_ARENA_SLICE_SIZE + 1) : (MI_PU(1) << vbits)));
60	  const size_t page_map_size = (MI_ZU(1) << (vbits - MI_ARENA_SLICE_SHIFT));
61	  const bool commit = (page_map_size <= 1*MI_MiB || mi_option_is_enabled(mi_option_pagemap_commit)); // _mi_os_has_overcommit(); // commit on-access on Linux systems?
62	  const size_t commit_bits = _mi_divide_up(page_map_size, MI_PAGE_MAP_ENTRIES_PER_COMMIT_BIT);
63	  const size_t bitmap_size = (commit ? 0 : mi_bitmap_size(commit_bits, NULL));
64	  const size_t reserve_size = bitmap_size + page_map_size;
65	  mi_subproc_t* const subproc = _mi_subproc_main();
66	  uint8_t* const base = (uint8_t*)_mi_os_alloc_aligned(subproc, reserve_size, 1, commit, true /* allow large */, &mi_page_map_memid);
67	  if (base==NULL) {
68	    _mi_error_message(ENOMEM, "unable to reserve virtual memory for the page map (%zu KiB)\n", page_map_size / MI_KiB);
69	    return false;
70	  }
71	  if (mi_page_map_memid.initially_committed && !mi_page_map_memid.initially_zero) {
72	    _mi_warning_message("internal: the page map was committed but not zero initialized!\n");
73	    _mi_memzero_aligned(base, reserve_size);
74	  }
75	  if (bitmap_size > 0) {
76	    mi_page_map_commit = (mi_bitmap_t*)base;
77	    if (!_mi_os_commit(subproc, mi_page_map_commit, bitmap_size, NULL)) {
78	      mi_page_map_cannot_commit();
79	      return false;
80	    }
81	    mi_bitmap_init(mi_page_map_commit, commit_bits, true);
82	  }
83	  mi_atomic_store_ptr_release(uint8_t,&_mi_page_map, base + bitmap_size);
84	
85	  // commit the first part so NULL pointers get resolved without an access violation
86	  if (!commit) {
87	    if (!mi_page_map_ensure_committed(0, 1)) {
88	      mi_page_map_cannot_commit();
89	      return false;
90	    }
91	  }
92	  mi_atomic_load_ptr_relaxed(uint8_t, &_mi_page_map)[0] = 1; // so _mi_ptr_page(NULL) == NULL
93	  mi_assert_internal(_mi_ptr_page(NULL)==NULL);
94	  return true;
95	}
96	
97	void _mi_page_map_unsafe_destroy(void) {
98	  mi_assert_internal(mi_atomic_load_ptr_relaxed(uint8_t, &_mi_page_map) != NULL);
99	  if (mi_atomic_load_ptr_relaxed(uint8_t, &_mi_page_map) == NULL) return;
100	  _mi_os_free_ex(_mi_subproc_main(), mi_page_map_memid.mem.os.base, mi_page_map_memid.mem.os.size, true, mi_page_map_memid);
101	  mi_atomic_store_ptr_release(uint8_t, &_mi_page_map, NULL);
102	  mi_page_map_commit = NULL;
103	  mi_atomic_store_ptr_release(void, &_mi_page_map_max_address, NULL);
104	  mi_page_map_memid = _mi_memid_none();
105	}
