107	
108	static bool mi_page_map_ensure_committed(size_t idx, size_t slice_count) {
109	  // is the page map area that contains the page address committed?
110	  // we always set the commit bits so we can track what ranges are in-use.
111	  // we only actually commit if the map wasn't committed fully already.
112	  uint8_t* const page_map = mi_atomic_load_ptr_relaxed(uint8_t,&_mi_page_map);
113	  if (mi_page_map_commit != NULL) {
114	    const size_t commit_idx = idx / MI_PAGE_MAP_ENTRIES_PER_COMMIT_BIT;
115	    const size_t commit_idx_hi = (idx + slice_count - 1) / MI_PAGE_MAP_ENTRIES_PER_COMMIT_BIT;
116	    for (size_t i = commit_idx; i <= commit_idx_hi; i++) {  // per bit to avoid crossing over bitmap chunks
117	      if (mi_bitmap_is_clear(mi_page_map_commit, i)) {
118	        // this may race, in which case we do multiple commits (which is ok)
119	        bool is_zero;
120	        uint8_t* const start = page_map + (i * MI_PAGE_MAP_ENTRIES_PER_COMMIT_BIT);
121	        const size_t   size  = MI_PAGE_MAP_ENTRIES_PER_COMMIT_BIT;
122	        if (!_mi_os_commit(_mi_subproc_main(), start, size, &is_zero)) {
123	          mi_page_map_cannot_commit();
124	          return false;
125	        }
126	        if (!is_zero && !mi_page_map_memid.initially_zero) { _mi_memzero(start, size); }
127	        mi_bitmap_set(mi_page_map_commit, i);
128	      }
129	    }
130	  }
131	  #if MI_DEBUG > 0
132	  page_map[idx] = 0;
133	  page_map[idx+slice_count-1] = 0;
134	  #endif
135	  return true;
136	}
