147	bool _mi_page_map_register(mi_page_t* page) {
148	  mi_assert_internal(page != NULL);
149	  mi_assert_internal(_mi_is_aligned(mi_page_slice_start(page), MI_PAGE_ALIGN));
150	  mi_assert_internal(mi_atomic_load_ptr_relaxed(uint8_t,&_mi_page_map) != NULL);  // should be initialized before multi-thread access!
151	  uint8_t* page_map = mi_atomic_load_ptr_relaxed(uint8_t,&_mi_page_map);
152	  if mi_unlikely(mi_atomic_load_ptr_relaxed(uint8_t,&_mi_page_map) == NULL) {
153	    if (!_mi_page_map_init()) return false;
154	    page_map = mi_atomic_load_ptr_acquire(uint8_t,&_mi_page_map);
155	  }
156	  mi_assert(page_map!=NULL);
157	  uint8_t* page_start;
158	  size_t   slice_count;
159	  const size_t idx = mi_page_map_get_idx(page, &page_start, &slice_count);
160	
161	  if (!mi_page_map_ensure_committed(idx, slice_count)) {
162	    return false;
163	  }
164	
165	  // set the offsets
166	  for (size_t i = 0; i < slice_count; i++) {
167	    mi_assert_internal(i < 128);
168	    page_map[idx + i] = (uint8_t)(i+1);
169	  }
170	  return true;
171	}
172	
173	void _mi_page_map_unregister(mi_page_t* page) {
174	  uint8_t* const page_map = mi_atomic_load_ptr_relaxed(uint8_t,&_mi_page_map);
175	  mi_assert_internal(page_map != NULL);
176	  if (page_map == NULL) return;
177	  // get index and count
178	  uint8_t* page_start;
179	  size_t   slice_count;
180	  const size_t idx = mi_page_map_get_idx(page, &page_start, &slice_count);
181	  // unset the offsets
182	  _mi_memzero(page_map + idx, slice_count);
183	}
184	
185	void _mi_page_map_unregister_range(void* start, size_t size) {
186	  uint8_t* const page_map = mi_atomic_load_ptr_relaxed(uint8_t,&_mi_page_map);
187	  mi_assert_internal(page_map!=NULL);
188	  if (page_map == NULL) return;
189	  const size_t slice_count = _mi_divide_up(size, MI_ARENA_SLICE_SIZE);
190	  const uintptr_t index = _mi_page_map_index(start);
191	  // todo: scan the commit bits and clear only those ranges?
192	  if (!mi_page_map_ensure_committed(index, slice_count)) { // we commit the range in total;
193	    return;
194	  }
195	  _mi_memzero(&page_map[index], slice_count);
196	}
