198	
199	mi_page_t* _mi_safe_ptr_page(const void* p) {
200	  if mi_unlikely(p >= mi_atomic_load_ptr_relaxed(void, &_mi_page_map_max_address)) return NULL;
201	  const uintptr_t idx = _mi_page_map_index(p);
202	  if mi_unlikely(mi_page_map_commit != NULL && !mi_bitmap_is_set(mi_page_map_commit, idx/MI_PAGE_MAP_ENTRIES_PER_COMMIT_BIT)) return NULL;
203	  const uintptr_t ofs = _mi_page_map_at(idx);
204	  if mi_unlikely(ofs == 0) return NULL;
205	  return (mi_page_t*)((((uintptr_t)p >> MI_ARENA_SLICE_SHIFT) - ofs + 1) << MI_ARENA_SLICE_SHIFT);
206	}
207	
208	mi_decl_nodiscard mi_decl_export bool mi_is_in_heap_region(const void* p) mi_attr_noexcept {
209	  return (_mi_safe_ptr_page(p) != NULL);
210	}
