212	#else
213	
214	// A 2-level page map
215	#define MI_PAGE_MAP_SUB_SIZE          (MI_PAGE_MAP_SUB_COUNT * sizeof(mi_page_t*))
216	
217	// Use an initial empty page map so `free(NULL)` works even if mimalloc is not yet initialized (issue #1341)
218	static mi_page_map_t mi_page_map_empty = { 
219	  MI_ATOMIC_VAR_INIT(1),
220	  sizeof(mi_page_map_t),
221	  MI_MEMID_STATIC,
222	  MI_LOCK_INITIALIZER,
223	  { MI_ATOMIC_VAR_INIT(NULL) } 
224	};
225	
226	mi_decl_hidden mi_decl_cache_align _Atomic(mi_page_map_t*) __mi_page_map  = MI_ATOMIC_VAR_INIT(&mi_page_map_empty);
227	
228	static size_t mi_page_map_count_of_size(size_t size) {
229	  return (size < sizeof(mi_page_map_t) ? 0 : 1 + (size - sizeof(mi_page_map_t))/sizeof(mi_submap_t));
230	}
