236	mi_decl_nodiscard static mi_decl_noinline bool mi_page_map_commit_entries(mi_page_map_t* pmap, size_t required_idx) {
237	  const size_t reserved_count = mi_page_map_count_of_size(pmap->reserved_size);  
238	  if mi_unlikely(required_idx >= reserved_count) {
239	    mi_page_map_cannot_commit(); 
240	    return false;
241	  }
242	  size_t commit_size = _mi_align_up( sizeof(mi_page_map_t) + (required_idx * sizeof(mi_submap_t)), MI_ARENA_SLICE_SIZE );
243	  if (pmap->reserved_size < commit_size) { commit_size = pmap->reserved_size; }
244	  const size_t commit_count = mi_page_map_count_of_size(commit_size);
245	  mi_assert_internal(commit_count > required_idx);
246	  mi_assert_internal(commit_count <= reserved_count);
247	  // note: we rely on uncommitted memory to be zero initialized on the first commit (and further concurrent commits leave the memory as is).
248	  bool is_zero;
249	  if mi_unlikely(!_mi_os_commit(_mi_subproc_main(), pmap, commit_size, &is_zero)) {
250	    mi_page_map_cannot_commit();
251	    return false;
252	  }
253	  mi_assert_internal(is_zero || pmap->memid.initially_zero);
254	  mi_atomic_store_release(&pmap->committed_count, commit_count); 
255	  // mi_atomic_store_release(&pmap->committed_addr, mi_page_map_addr_of_index(commit_count));
256	  return true;
257	}
258	
259	mi_decl_nodiscard static bool mi_page_map_ensure_committed(mi_page_map_t* pmap, size_t idx, mi_submap_t* submap) {
260	  mi_assert_internal(submap!=NULL && *submap==NULL);
261	  if mi_unlikely(idx >= mi_atomic_load_relaxed(&pmap->committed_count)) {
262	    if (idx >= mi_atomic_load_acquire(&pmap->committed_count)) {
263	      if (!mi_page_map_commit_entries(pmap,idx)) return false;    
264	      mi_assert_internal(idx < mi_atomic_load_relaxed(&pmap->committed_count));
265	    }
266	  }
267	  *submap = mi_atomic_load_ptr_acquire(mi_page_t*, &pmap->submaps[idx]);
268	  return true;
269	}
