271	// initialize the page map 
272	static bool mi_page_map_init_once(void) {
273	  size_t vbits = (size_t)mi_option_get_clamp(mi_option_max_vabits, 0, MI_MAX_VABITS);
274	  if (vbits == 0) {
275	    vbits = _mi_os_virtual_address_bits();
276	    #if MI_ARCH_X64  // canonical address is limited to the first 128 TiB
277	    if (vbits >= 48) { vbits = 47; }
278	    #endif
279	  }
280	  if (vbits < MI_PAGE_MAP_SUB_SHIFT + MI_ARENA_SLICE_SHIFT) {
281	    vbits = MI_PAGE_MAP_SUB_SHIFT + MI_ARENA_SLICE_SHIFT;
282	  }
283	  if (vbits < MI_MIN_VABITS) {    // cover at least this much for a faster _mi_checked_ptr
284	    vbits = MI_MIN_VABITS;
285	  }
286	  if (vbits > MI_MAX_VABITS) {    // limit page map size even if more virtual addresses are available
287	    vbits = MI_MAX_VABITS;
288	  }
289	
290	  // Allocate the page map and commit bits
291	  mi_assert(MI_MAX_VABITS >= vbits);
292	  mi_assert(MI_MIN_VABITS <= vbits);
293	  const size_t reserve_count    = (MI_ZU(1) << (vbits - MI_PAGE_MAP_SUB_SHIFT - MI_ARENA_SLICE_SHIFT));
294	  const size_t os_page_size  = _mi_os_page_size();
295	  const size_t reserve_size  = _mi_align_up( sizeof(mi_page_map_t) + ((reserve_count - 1) * sizeof(mi_submap_t)), os_page_size);
296	  const size_t submap_size   = MI_PAGE_MAP_SUB_SIZE;
297	  const size_t extra_reserve_size  = reserve_size + submap_size;
298	  const bool commit = (vbits == MI_MIN_VABITS) || (reserve_size <= 64*MI_KiB) || // 42 virtual address bits
299	                      mi_option_is_enabled(mi_option_pagemap_commit) || _mi_os_has_overcommit();
300	  mi_subproc_t* const subproc = _mi_subproc_main();
301	  mi_memid_t memid;
302	  mi_page_map_t* const pmap = (mi_page_map_t*)_mi_os_alloc_aligned(subproc, extra_reserve_size, 1, commit, true /* allow large */, &memid);
303	  if mi_unlikely(pmap==NULL) {
304	    _mi_error_message(ENOMEM, "unable to reserve virtual memory for the page map (%zu KiB)\n", extra_reserve_size / MI_KiB);
305	    return false;
306	  }
307	 
308	  // commit 
309	  size_t commit_count;
310	  if (memid.initially_committed) {
311	    if (!memid.initially_zero) {
312	      _mi_warning_message("internal: the page map was committed but not zero initialized!\n");
313	      _mi_memzero_aligned(pmap, extra_reserve_size);
314	      memid.initially_zero = true;
315	    }
316	    commit_count = mi_page_map_count_of_size(reserve_size);
317	  }
318	  else {
319	    // commit first entries up to MI_MIN_VABITS entries
320	    const size_t min_commit_count = (MI_ZU(1) << (MI_MIN_VABITS - MI_PAGE_MAP_SUB_SHIFT - MI_ARENA_SLICE_SHIFT));  
321	    const size_t min_commit_size = _mi_align_up( sizeof(mi_page_map_t) + ((min_commit_count-1) * sizeof(mi_submap_t)), os_page_size);
322	    mi_assert_internal(min_commit_size <= reserve_size);
323	    bool is_zero;
324	    if (!_mi_os_commit(subproc,pmap,min_commit_size,&is_zero)) {
325	      mi_page_map_cannot_commit();
326	      _mi_os_free(subproc,pmap,extra_reserve_size,memid);
327	      return false;
328	    };
329	    mi_assert_internal(is_zero || memid.initially_zero);
330	    commit_count = mi_page_map_count_of_size(min_commit_size);
331	    mi_assert_internal(commit_count >= min_commit_count);
332	  }
333	  
334	  // ensure there is a submap for the NULL address
335	  mi_page_t** const sub0 = (mi_submap_t)((uint8_t*)pmap + reserve_size);  // we reserved a submap part at the end already
336	  if (!memid.initially_committed) {
337	    if (!_mi_os_commit(subproc, sub0, submap_size, NULL)) {  // commit full submap (issue #1087)
338	      mi_page_map_cannot_commit();
339	      _mi_os_free(subproc,pmap,extra_reserve_size,memid);
340	      return false;
341	    }
342	  }
343	  if (!memid.initially_zero) {     // initialize low addresses with NULL
344	    _mi_memzero_aligned(sub0, submap_size);
345	  }
346	
347	  // initialize the fields
348	  pmap->memid = memid;
349	  pmap->reserved_size  = reserve_size;
350	  mi_lock_init(&pmap->lock);
351	  mi_atomic_store_release(&pmap->committed_count, commit_count);
352	  // mi_atomic_store_release(&pmap->committed_addr, mi_page_map_addr_of_index(commit_count));
353	  mi_atomic_store_ptr_release(mi_page_t*, &pmap->submaps[0], sub0);
354	  mi_atomic_store_ptr_release(mi_page_map_t, &__mi_page_map, pmap);
355	  mi_assert_internal(_mi_ptr_page(NULL)==NULL);
356	  return true;
357	}
358	
359	bool _mi_page_map_init(void) {
360	  bool ok = true;
361	  mi_atomic_do_once {
362	    ok = mi_page_map_init_once();
363	  }
364	  return ok;
365	}
366	
367	void _mi_page_map_unsafe_destroy(void) {
368	  mi_page_map_t* const pmap = _mi_page_map();
369	  mi_assert_internal(pmap != NULL);
370	  if (pmap == NULL || pmap == &mi_page_map_empty) return;
371	  mi_subproc_t* const subproc = _mi_subproc_main();
372	  mi_lock_done(&pmap->lock);  
373	  for (size_t idx = 1; idx < pmap->committed_count; idx++) {  // skip entry 0 (as we allocate that submap at the end of the page_map)
374	    // free all sub-maps   
375	    mi_submap_t sub = _mi_page_map_at(pmap,idx);
376	    if (sub != NULL) {
377	      mi_memid_t memid = _mi_memid_create_os(sub, MI_PAGE_MAP_SUB_SIZE, true, false, false);
378	      _mi_os_free_ex(subproc, memid.mem.os.base, memid.mem.os.size, true, memid);
379	      mi_atomic_store_ptr_release(mi_page_t*, &pmap->submaps[idx], NULL);
380	    }
381	  }
382	  _mi_os_free_ex(subproc, pmap, pmap->reserved_size, true, pmap->memid);
383	  mi_atomic_store_ptr_release(mi_page_map_t, &__mi_page_map, &mi_page_map_empty);  
384	}
