386	mi_decl_nodiscard static mi_decl_noinline mi_submap_t mi_page_map_alloc_submap_at(mi_page_map_t* pmap, size_t idx) {
387	  // sub map not yet allocated, alloc now
388	  mi_submap_t sub = NULL;
389	  mi_lock(&pmap->lock) 
390	  {
391	    sub = mi_atomic_load_ptr_acquire(mi_page_t*, &pmap->submaps[idx]); // reload
392	    if (sub==NULL) // not yet allocated by another thread?      
393	    {
394	      mi_subproc_t* const subproc = _mi_subproc_main();
395	      mi_memid_t memid;
396	      const size_t submap_size = MI_PAGE_MAP_SUB_SIZE;        
397	      sub = (mi_submap_t)_mi_os_zalloc(subproc, submap_size, &memid);        
398	      if (sub==NULL) {
399	        _mi_warning_message("internal error: unable to extend the page map\n");          
400	      }
401	      else {
402	        mi_submap_t expect = NULL;
403	        if (!mi_atomic_cas_ptr_strong_acq_rel(mi_page_t*, &pmap->submaps[idx], &expect, sub)) {
404	          // another thread already allocated it.. free and continue
405	          _mi_os_free(subproc, sub, submap_size, memid);
406	          sub = expect;
407	        }
408	      }
409	    }
410	  }
411	  return sub;
412	}
413	
414	mi_decl_nodiscard static bool mi_page_map_ensure_submap_at(mi_page_map_t* pmap, size_t idx, mi_submap_t* submap) {
415	  mi_assert_internal(submap!=NULL && *submap==NULL);
416	  mi_submap_t sub = NULL;
417	  if (!mi_page_map_ensure_committed(pmap, idx, &sub)) {
418	    return false;
419	  }
420	  if mi_unlikely(sub==NULL) {
421	    sub = mi_page_map_alloc_submap_at(pmap, idx);
422	    if (sub==NULL) return false; // unable to allocate the submap..
423	  }
424	  mi_assert_internal(sub!=NULL);
425	  *submap = sub;
426	  return true;
427	}
428	
429	static bool mi_page_map_set_range_prim(mi_page_map_t* pmap, mi_page_t* page, size_t idx, size_t sub_idx, size_t slice_count) {
430	  // is the page map area that contains the page address committed?
431	  while (slice_count > 0) {
432	    mi_submap_t sub = NULL;
433	    if (!mi_page_map_ensure_submap_at(pmap, idx, &sub)) {
434	      return false;
435	    };
436	    mi_assert_internal(sub!=NULL);
437	    // set the offsets for the page
438	    while (slice_count > 0 && sub_idx < MI_PAGE_MAP_SUB_COUNT) {
439	      sub[sub_idx] = page;
440	      slice_count--;
441	      sub_idx++;
442	    }
443	    idx++; // potentially wrap around to the next idx
444	    sub_idx = 0;
445	  }
446	  return true;
447	}
448	
449	static bool mi_page_map_set_range(mi_page_map_t* pmap, mi_page_t* page, size_t idx, size_t sub_idx, size_t slice_count) {
450	  if mi_unlikely(!mi_page_map_set_range_prim(pmap, page,idx,sub_idx,slice_count)) {
451	    // failed to commit, call again to reset the page pointer if needed
452	    if (page!=NULL) {
453	      mi_page_map_set_range_prim(pmap,NULL,idx,sub_idx,slice_count);
454	    }
455	    return false;
456	  }
457	  return true;
458	}
459	
460	static size_t mi_page_map_get_idx(mi_page_t* page, size_t* sub_idx, size_t* slice_count) {
461	  size_t page_size;
462	  uint8_t* page_start = mi_page_area(page, &page_size);
463	  if (page_size > MI_LARGE_PAGE_SIZE) { page_size = MI_LARGE_PAGE_SIZE - MI_ARENA_SLICE_SIZE; }  // furthest interior pointer
464	  *slice_count = mi_slice_count_of_size(page_size) + ((page_start - mi_page_slice_start(page))/MI_ARENA_SLICE_SIZE); // add for large aligned blocks
465	  return _mi_page_map_index(page_start, sub_idx);
466	}
467	
468	bool _mi_page_map_register(mi_page_t* page) {
469	  mi_assert_internal(page != NULL);
470	  mi_assert_internal(_mi_is_aligned(mi_page_slice_start(page), MI_PAGE_ALIGN));
471	  mi_page_map_t* pmap = _mi_page_map();
472	  mi_assert_internal(pmap != NULL);  // should be initialized before multi-thread access!
473	  if mi_unlikely(pmap == NULL) {
474	    if (!_mi_page_map_init()) return false;
475	    pmap = mi_atomic_load_ptr_acquire(mi_page_map_t,&__mi_page_map);
476	  }
477	  mi_assert(pmap!=NULL);
478	  size_t   slice_count;
479	  size_t   sub_idx;
480	  const size_t idx = mi_page_map_get_idx(page, &sub_idx, &slice_count);
481	  return mi_page_map_set_range(pmap, page, idx, sub_idx, slice_count);
482	}
483	
484	void _mi_page_map_unregister(mi_page_t* page) {
485	  mi_assert_internal(_mi_page_map != NULL);
486	  mi_assert_internal(page != NULL);
487	  mi_assert_internal(_mi_is_aligned(mi_page_slice_start(page), MI_PAGE_ALIGN));
488	  mi_page_map_t* const pmap = _mi_page_map();
489	  // note: should proceed even if the page was not registered yet (for failure paths in page allocation in `arena.c`)
490	  if mi_unlikely(pmap == NULL) return;
491	  // get index and count
492	  size_t slice_count;
493	  size_t sub_idx;
494	  const size_t idx = mi_page_map_get_idx(page, &sub_idx, &slice_count);
495	  // unset the offsets
496	  mi_page_map_set_range(pmap, NULL, idx, sub_idx, slice_count);
497	}
498	
499	void _mi_page_map_unregister_range(void* start, size_t size) {
500	  mi_page_map_t* const pmap = _mi_page_map();
501	  if mi_unlikely(pmap == NULL) return;
502	  const size_t slice_count = _mi_divide_up(size, MI_ARENA_SLICE_SIZE);
503	  size_t sub_idx;
504	  const uintptr_t idx = _mi_page_map_index(start, &sub_idx);
505	  mi_page_map_set_range(pmap, NULL, idx, sub_idx, slice_count);  // todo: avoid committing if not already committed?
506	}
507	
508	// Return NULL for invalid pointers
509	mi_page_t* _mi_safe_ptr_page(const void* p) {
510	  return _mi_checked_ptr_page(p);
511	}
512	
513	mi_decl_nodiscard mi_decl_export bool mi_is_in_heap_region(const void* p) mi_attr_noexcept {
514	  return (_mi_safe_ptr_page(p) != NULL);
515	}
516	
517	#endif
518

